def transform(grid):
    # Remove singleton noise; keep background and all rectangular colored figures.
    h,w=len(grid),len(grid[0])
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]
    # components made of any non-background color, including shapes with holes/punctures
    seen=set()
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col==bg or (r,c) in seen: continue
            # each color's shape often broken by distractor 4s; recover contiguous full grid rectangle
            # classify based on region of repeated dominant color; use all pixels of this color
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
                        seen.add((yy,xx));stack.append((yy,xx))
            if len(cells)>=8:
                for y,x in cells: out[y][x]=col
    return out

